    # Helper: convert integer color code to color name
    # ------------------------------------------------------------
    INT_TO_COLOR = {
        0: "black",
        1: "blue",
        2: "red",
        3: "green",
        4: "yellow",
        5: "light-gray",
        6: "magenta",
        7: "orange",
        8: "light-blue",
        9: "dark-red",
        10: "white",
        11: "dark-gray",
    }

    def color_name(val):
        if isinstance(val, int):
            return INT_TO_COLOR.get(val, f"color{val}")
        # for autumn strings, use the string as-is
        return str(val)

    # ------------------------------------------------------------
    # Helper: collect non-background cells into feature strings
    # ------------------------------------------------------------
