import json
import ast
import re
from typing import List, Tuple, Optional

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation from observation_history[-1] and return a
    concise summary of decision-relevant features as a string.
    The output is always non‑empty and never raises an exception.
    """
    obs = observation_history[-1] if observation_history else ""

    # ------------------------------------------------------------------
    # Helper: extract metadata (step, action count, levels)
    # ------------------------------------------------------------------
    step = None
    action_count = None
    # levels = None   # optional: could be added later
    try:
        m = re.search(r"Step:\s*(\d+)", obs)
        if m:
            step = int(m.group(1))
        m = re.search(r"Action count:\s*(\d+)", obs)
        if m:
            action_count = int(m.group(1))
        # m = re.search(r"Levels completed:\s*(\d+/\d+)", obs)
        # if m: levels = m.group(1)
    except Exception:
        pass

    meta_parts = []
    if step is not None:
        meta_parts.append(f"step={step}")
    if action_count is not None:
        meta_parts.append(f"act={action_count}")

    # ------------------------------------------------------------------
    # Color name mapping
    # ------------------------------------------------------------------
    INT_TO_COLOR = {
        0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
        5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
        9: "dark-red", 10: "white", 11: "dark-gray",
    }

    def color_name(val):
        if isinstance(val, int):
            return INT_TO_COLOR.get(val, f"color{val}")
        return str(val)

    # ------------------------------------------------------------------
    # Helper: extract the first top-level JSON array from text
    # ------------------------------------------------------------------
    def extract_json_array(text: str) -> Optional[List]:
        """Return the Python list from the first top-level JSON array in text."""
        counter = 0
        start = -1
        for i, ch in enumerate(text):
            if ch == '[':
                if counter == 0:
                    start = i
                counter += 1
            elif ch == ']':
                counter -= 1
                if counter == 0 and start != -1:
                    try:
                        return json.loads(text[start:i+1])
                    except Exception:
                        # even if this fails, continue scanning for other arrays?
                        # but there should be only one large array
                        pass
        return None

    # ------------------------------------------------------------------
    # Helper: extract non‑background cells and grid dimensions
    # ------------------------------------------------------------------
    def extract_features(grid: List[List]) -> Tuple[List[str], int, int]:
        feature_tuples = []
        height = len(grid)
        width = len(grid[0]) if height > 0 else 0
        for r, row in enumerate(grid):
            for c, cell in enumerate(row):
                # Determine if cell is background (black)
                if isinstance(cell, int):
                    is_bg = cell == 0
                else:
                    is_bg = cell == "black"
                if not is_bg:
                    feature_tuples.append((color_name(cell), r, c))
        feature_tuples.sort(key=lambda x: (x[0], x[1], x[2]))
        feature_strs = [f"{color} at ({r},{c})" for color, r, c in feature_tuples]
        return feature_strs, height, width

    # ------------------------------------------------------------------
    # Try to parse the grid (ARC integer format or Autumn JSON format)
    # ------------------------------------------------------------------
    grid = None
    height = width = 0

    # --- Attempt 1: ARC integer grid marker ---
    if "<grid_" in obs:
        try:
            lines = obs.splitlines()
            rows = []
            in_grid = False
            for line in lines:
                stripped = line.strip()
                if stripped.startswith("<grid_"):
                    in_grid = True
                    continue
                if in_grid:
                    if stripped.startswith("["):
                        try:
                            row = ast.literal_eval(stripped)
                            if isinstance(row, list):
                                rows.append(row)
                        except Exception:
                            pass
                    else:
                        # End of current grid block
                        if rows:
                            break
            if rows:
                grid = rows
        except Exception:
            pass

    # --- Attempt 2: Autumn JSON array (if not already parsed) ---
    if grid is None:
        try:
            parsed = extract_json_array(obs)
            if parsed and isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], list):
                grid = parsed
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Build the output string
    # ------------------------------------------------------------------
    meta_str = " | ".join(meta_parts) if meta_parts else ""

    if grid is not None:
        feature_strs, h, w = extract_features(grid)
        size_str = f"grid {h}x{w}" if h > 0 and w > 0 else "grid unknown"
        feat_str = ", ".join(feature_strs) if feature_strs else "[]"
        if meta_str:
            out = f"{meta_str} | {size_str} | {feat_str}"
        else:
            out = f"{size_str} | {feat_str}"
    else:
        # Grid could not be parsed – at least return metadata
        if meta_str:
            out = f"{meta_str} | grid unknown | []"
        else:
            out = "grid unknown | []"

    # Ensure output is not empty (it never should be, but just in case)
    if not out.strip():
        out = "no data"

    return out

