        result = " | ".join(parts) + " | " + str(feat_strs)

        # Truncate if needed (keep important metadata)
        if len(result) > 2000:
            # Only keep first 20 features
            feat_strs = feat_strs[:20] if isinstance(feat_strs, list) else [feat_strs]
